# hypothesis: A plain class attribute can implement an abstract property, and a class that leaves any abstract member unimplemented must be rejected on instantiation.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        ...

    @abstractmethod
    def area(self) -> float:
        ...


class Square(Shape):
    sides: int = 4  # plain attribute implements the abstract property

    def __init__(self, edge: float) -> None:
        self.edge = edge

    def area(self) -> float:
        return self.edge * self.edge


class Blob(Shape):  # implements sides as a property but not area
    @property
    def sides(self) -> int:
        return 0


sq = Square(2.0)
reveal_type(sq.sides)
reveal_type(sq.area())
print(sq.sides, sq.area())
try:
    Shape()  # expect-error: cannot instantiate abstract class Shape
except TypeError as exc:
    print('runtime:', type(exc).__name__)
try:
    Blob()  # expect-error: Blob still has abstract method area
except TypeError as exc:
    print('runtime:', type(exc).__name__)
